import fs from 'node:fs/promises';
import path from 'node:path';
import {products,ui,contact} from './src/content.mjs';
const out=path.resolve('dist');
const siteURL=new URL(process.env.SITE_URL||'https://www.sagarlabs.com').origin;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slugs={es:{home:'',cybercat:'cybercat',infra:'infraestructura',research:'investigacion',sample:'muestra-informe',about:'nosotros',contact:'contacto',privacy:'privacidad'},en:{home:'',cybercat:'cybercat',infra:'infrastructure',research:'materials',sample:'sample-brief',about:'about',contact:'contact',privacy:'privacy'}};
const href=(lang,key)=>`/${lang}/${key.startsWith('product:')?slugs[lang].research+'/'+key.slice(8):slugs[lang][key]}/`.replace(/\/+/g,'/');
const choose=(l,es,en)=>l==='es'?es:en;
const icon='<span aria-hidden="true">↗</span>';
const button=(url,label,variant='lime')=>`<a class="button ${variant}" href="${esc(url)}">${esc(label)}${icon}</a>`;
function eyebrow(text){return `<p class="eyebrow">${esc(text)}</p>`}
function sectionTitle(label,title,description=''){return `<div class="section-heading"><div>${eyebrow(label)}<h2>${title}</h2></div>${description?`<p>${description}</p>`:''}</div>`}
function showcase(l){return `<figure class="blender-showcase"><div class="showcase-title">${eyebrow('SL / 005 + SL / 006')}<h2>${choose(l,'Conceptos en escena.','Concepts on display.')}</h2><p>${choose(l,'Gemelo digital de baterías y arquitectura de centro de datos.','Battery digital twin and data center architecture.')}</p></div><img src="/assets/sl005-sl006-showcase.png" alt="${choose(l,'Render conceptual de Blender con dos propuestas de producto sobre pedestales iluminados','Conceptual Blender render of two product proposals on illuminated pedestals')}" width="1920" height="1080" loading="lazy"><figcaption><span>${choose(l,'Render de Blender facilitado por Sagar Labs. Representación conceptual; no es una fotografía de prototipos ni una validación de prestaciones.','Blender render supplied by Sagar Labs. A conceptual representation, not a prototype photograph or performance validation.')}</span><a href="/assets/sl005-sl006-showcase.png" download>${choose(l,'Descargar render original','Download original render')} ↗</a></figcaption></figure>`}
function productArt(p,i){return `${p.render?`<img class="product-poster" src="${p.render}" alt="" loading="lazy" width="1000" height="800">`:''}${p.staticVisual?'':`<canvas class="product-canvas" data-piece="${i}" aria-hidden="true"></canvas>`}<span class="piece-number">SL / ${String(i+1).padStart(3,'0')}</span><span class="piece-formula">${esc(p.formula)}</span>`}
function card(l,p,i){const t=ui[l],v=p[l];return `<article class="product" data-filter="${p.filter}" data-piece="${i}"><a class="product-art" href="${href(l,'product:'+p.slug)}" aria-label="${esc(v.title)}">${productArt(p,i)}<span class="piece-open">${choose(l,'Explorar','Explore')} ↗</span></a><p class="product-category">${esc(v.category)}</p><h3><a href="${href(l,'product:'+p.slug)}">${esc(v.title)}</a></h3><p class="product-summary">${esc(v.summary)}</p>${v.price?`<p class="product-price">${esc(v.price)}<small>${choose(l,'REFERENCIA COMERCIAL · SUJETA A ALCANCE','COMMERCIAL REFERENCE · SUBJECT TO SCOPE')}</small></p>`:''}<p class="research-state">${esc(v.status||t.researchStatus)}</p><a class="text-link" href="${href(l,'product:'+p.slug)}">${choose(l,'Ver ficha y datos reportados','View brief and reported data')} ↗</a></article>`}
function cta(l,type='pilot'){const t=ui[l];return `<section class="cta-strip"><div>${eyebrow(choose(l,'EL SIGUIENTE PASO','THE NEXT STEP'))}<h2>${choose(l,'Una pregunta concreta.<br><em>Un alcance que podamos evaluar.</em>','One specific question.<br><em>A scope we can evaluate.</em>')}</h2></div>${button(href(l,'contact')+'?type='+type,t.evaluate)}</section>`}
function samplePreview(l){return `<div class="brief-preview"><div class="brief-preview-top"><span>SL / DECISION BRIEF</span><span>${esc(ui[l].sampleShort)}</span></div><h3>${choose(l,'¿Qué necesitamos saber<br>antes de ensayar?','What do we need to know<br>before testing?')}</h3><div class="evidence-row"><span class="evidence-dot known"></span><div><strong>${choose(l,'Hecho proporcionado','Provided fact')}</strong><p>${choose(l,'Existe una propuesta de material. Sus datos deben revisarse.','A material proposal exists. Its data needs review.')}</p></div></div><div class="evidence-row"><span class="evidence-dot hypothesis"></span><div><strong>${choose(l,'Hipótesis por evaluar','Hypothesis to evaluate')}</strong><p>${choose(l,'Podría justificar ensayos comparativos bajo condiciones acordadas.','It may justify comparative testing under agreed conditions.')}</p></div></div><div class="evidence-row"><span class="evidence-dot unknown"></span><div><strong>${choose(l,'Pregunta abierta','Open question')}</strong><p>${choose(l,'¿Qué incertidumbre cambia la decisión de continuar?','Which uncertainty changes the decision to continue?')}</p></div></div><a class="text-link" href="${href(l,'sample')}">${esc(ui[l].sample)} ↗</a></div>`}
function home(l){const t=ui[l];return `<section class="hero compact-hero"><div class="hero-top"><span><i></i>${choose(l,'INTELIGENCIA PARA EL MUNDO FÍSICO','INTELLIGENCE FOR THE PHYSICAL WORLD')}</span><span>SAGAR LABS / 2026</span></div><div class="hero-copy">${eyebrow(choose(l,'INFRAESTRUCTURA · INVESTIGACIÓN APLICADA','INFRASTRUCTURE · APPLIED RESEARCH'))}<h1>${choose(l,'De preguntas<br>a <em>decisiones.</em>','From questions<br>to <em>decisions.</em>')}</h1><p class="hero-description">${choose(l,'Inteligencia de infraestructura e I+D asistida por IA<br>para equipos de energía, materiales y tecnología.','Infrastructure intelligence and AI-assisted R&D<br>for energy, materials and technology teams.')}</p><div class="hero-actions">${button(href(l,'contact'),t.evaluate)}<a class="hero-secondary" href="${href(l,'sample')}">${esc(t.sample)} ↓</a></div></div><canvas id="sculpture" aria-label="${choose(l,'Escultura helicoidal conceptual en movimiento','Conceptual helical sculpture in motion')}"></canvas><div class="hero-bottom"><span>${choose(l,'EVIDENCIA CLARA. LÍMITES EXPLÍCITOS.','CLEAR EVIDENCE. EXPLICIT LIMITATIONS.')}</span><a href="#services">${choose(l,'CONOCE LOS SERVICIOS','EXPLORE OUR SERVICES')} ↓</a></div></section><section class="section services-home" id="services">${sectionTitle(choose(l,'01 / QUÉ PUEDES CONTRATAR','01 / HOW WE CAN HELP'),choose(l,'Tres rutas.<br><em>Una pregunta como punto de partida.</em>','Three paths.<br><em>One question to start with.</em>'))}<div class="service-grid"><article id="infrastructure"><span class="service-index">01 / INTELLIGENCE</span><h3>${t.infrastructure}</h3><p>${choose(l,'Revisar energía, agua y restricciones de una ubicación antes de avanzar con una decisión de infraestructura.','Review power, water and site constraints before advancing an infrastructure decision.')}</p><a class="text-link" href="${href(l,'infra')}">${t.read} ↗</a></article><article id="cybercat"><span class="service-index">02 / CYBERCAT</span><h3>${choose(l,'I+D asistida por IA','AI-assisted R&D')}</h3><p>${choose(l,'Definir un piloto de investigación en materiales, baterías o sistemas térmicos, sujeto a viabilidad.','Scope a research pilot in materials, batteries or thermal systems, subject to feasibility.')}</p><span class="status">${t.status}</span><a class="text-link" href="${href(l,'cybercat')}">${t.read} ↗</a></article><article><span class="service-index">03 / RESEARCH</span><h3>${choose(l,'Investigación y licencias','Research & licensing')}</h3><p>${choose(l,'Explorar materiales, software y blueprints, su estado documental y las condiciones para una posible licencia.','Explore materials, software and blueprints, their documentary status and conditions for potential licensing.')}</p><a class="text-link" href="${href(l,'research')}">${t.explore} ↗</a></article></div></section><section class="section evidence-home" id="evidence"><div>${eyebrow(choose(l,'02 / EVALÚA EL ENTREGABLE','02 / EVALUATE THE DELIVERABLE'))}<h2>${choose(l,'Mira cómo se organiza<br><em>una decisión con evidencia.</em>','See how evidence<br><em>supports a decision.</em>')}</h2><p>${choose(l,'Una muestra de estructura, con preguntas, incertidumbres y criterios de avance. Está identificada como ilustrativa; no representa un resultado de cliente.','A sample structure with questions, uncertainties and decision gates. It is clearly illustrative and does not represent a client result.')}</p>${button(href(l,'sample'),t.sample,'dark')}</div>${samplePreview(l)}</section><section class="section company-home"><div>${eyebrow('03 / SAGAR LABS')}<h2>${choose(l,'Investigación con<br><em>responsabilidad y contexto.</em>','Research with<br><em>accountability and context.</em>')}</h2></div><div><p>${choose(l,'Sagar Labs es una empresa constituida en Estados Unidos. Nuestro enfoque conecta infraestructura física, investigación y criterios de decisión.','Sagar Labs is a company incorporated in the United States. Our approach connects physical infrastructure, research and decision criteria.')}</p><p>${choose(l,'El alcance, los responsables de revisión y las condiciones de cada proyecto deben quedar identificados antes de iniciar el trabajo.','The scope, review responsibilities and project terms must be identified before work begins.')}</p><a class="text-link" href="${href(l,'about')}">${t.nav[3]} ↗</a></div></section>${cta(l)}`}
function relatedProducts(l){return `<section class="section"><div class="section-heading"><div>${eyebrow(choose(l,'DEL PILOTO AL PRODUCTO','FROM PILOT TO PRODUCT'))}<h2>${choose(l,'Software y arquitectura.<br><em>Explora las propuestas.</em>','Software and architecture.<br><em>Explore the proposals.</em>')}</h2></div></div><div class="engagement-grid">${products.filter(p=>['bms-digital-twin-sdk','net-zero-ai-datacenter','titan-pikan-engine'].includes(p.slug)).map(p=>`<article><img class="related-product-img" src="${p.render}" alt="${choose(l,'Render conceptual de ','Conceptual render of ')+esc(p[l].title)}" loading="lazy" width="1000" height="800">${eyebrow(p[l].status)}<h3>${esc(p[l].title)}</h3><p>${esc(p[l].summary)}</p><a class="text-link" href="${href(l,'product:'+p.slug)}">${choose(l,'Explorar ficha y licencia','Explore brief and licensing')} ↗</a></article>`).join('')}</div></section>`}
function cybercat(l){const t=ui[l];return `<section class="page-intro dark-intro"><canvas id="field" aria-hidden="true"></canvas>${eyebrow('CYBERCAT / '+t.status)}<h1>${choose(l,'Tu pregunta de I+D.<br><em>Un piloto con dirección.</em>','Your R&D question.<br><em>A focused research pilot.</em>')}</h1><p>${choose(l,'CyberCat es un producto en evolución de Sagar Labs. Evaluamos proyectos para equipos de materiales, baterías y sistemas térmicos, con alcance y criterios de validación acordados.','CyberCat is an evolving Sagar Labs product. We assess projects for materials, battery and thermal systems teams, with agreed scope and validation criteria.')}</p><div class="intro-actions">${button(href(l,'contact')+'?type=pilot',choose(l,'Evaluar un piloto','Evaluate a pilot'))}<a class="text-link" href="${href(l,'sample')}">${t.sample} ↗</a></div></section><section class="section"><div class="two-column"><div>${eyebrow(choose(l,'EL ENCAJE DEL PROYECTO','PROJECT FIT'))}<h2>${choose(l,'Una decisión concreta.<br><em>Datos que podamos revisar.</em>','A specific decision.<br><em>Data we can review.</em>')}</h2></div><div><p>${choose(l,'El punto de partida puede ser una comparación de materiales, una pregunta sobre datos de ensayo o la revisión de un modelo. La aceptación depende de la disponibilidad y calidad de los datos y del método necesario.','The starting point may be a materials comparison, a test-data question or a model review. Acceptance depends on data availability and quality, and on the required method.')}</p><p>${choose(l,'Una propuesta comercial no demuestra por sí sola capacidad científica. Por eso, cada piloto acuerda qué se medirá, qué se entregará y qué no puede concluirse.','A commercial proposal alone does not demonstrate scientific capability. Each pilot therefore agrees on what will be measured, what will be delivered and what cannot be concluded.')}</p></div></div><div class="service-grid use-cases">${[
[choose(l,'Materiales','Materials'),choose(l,'¿Qué candidatos merecen una siguiente revisión?','Which candidates justify further review?'),choose(l,'Comparación documental y definición de un plan de evaluación.','Documentary comparison and an evaluation plan.')],
[choose(l,'Baterías','Batteries'),choose(l,'¿Qué limita la interpretación de los ensayos?','What limits interpretation of test data?'),choose(l,'Revisión de datos, métricas, referencias y separación entre entrenamiento y evaluación.','Review of data, metrics, baselines and separation between training and evaluation.')],
[choose(l,'Sistemas térmicos','Thermal systems'),choose(l,'¿Qué condiciones de operación importan?','Which operating conditions matter?'),choose(l,'Definición de hipótesis y condiciones para una comparación útil.','Definition of hypotheses and conditions for a useful comparison.')]
].map(([a,b,c])=>`<article><p class="eyebrow">${a}</p><h3>${b}</h3><p>${c}</p></article>`).join('')}</div></section><section class="section engagement-section">${sectionTitle(choose(l,'FORMAS DE TRABAJAR','ENGAGEMENT OPTIONS'),choose(l,'Empieza acotado.<br><em>Amplía con evidencia.</em>','Start focused.<br><em>Expand with evidence.</em>'))}<div class="engagement-grid"><article>${eyebrow(choose(l,'01 / ALCANCE FIJO','01 / FIXED SCOPE'))}<h3>${t.pilot}</h3><p>${choose(l,'Una pregunta, un plan y criterios para decidir si continuar.','One question, a plan and criteria for deciding whether to continue.')}</p><ul>${choose(l,['Revisión de viabilidad y datos disponibles','Alcance, calendario y presupuesto por propuesta','Informe con método, hallazgos, límites y próximos pasos'],['Review of feasibility and available data','Scope, schedule and budget by proposal','Report covering method, findings, limitations and next steps']).map(x=>`<li>${x}</li>`).join('')}</ul>${button(href(l,'contact')+'?type=pilot',choose(l,'Evaluar un piloto','Evaluate a pilot'))}</article><article>${eyebrow(choose(l,'02 / CONTINUIDAD','02 / CONTINUITY'))}<h3>${t.dedicated}</h3><p>${choose(l,'Para una agenda recurrente una vez confirmado el encaje.','For a recurring agenda once fit has been established.')}</p><ul>${choose(l,['Prioridades y entregables por hitos','Revisiones con el equipo del cliente','Recursos, confidencialidad y derechos definidos'],['Priorities and milestone-based deliverables','Reviews with the client team','Defined resources, confidentiality and rights']).map(x=>`<li>${x}</li>`).join('')}</ul>${button(href(l,'contact')+'?type=dedicated',choose(l,'Definir un programa','Scope a program'),'dark')}</article></div></section><section class="section two-column"><div>${eyebrow(choose(l,'ANTES DE INICIAR','BEFORE STARTING'))}<h2>${choose(l,'Lo que necesitas<br><em>tener claro.</em>','What you need<br><em>to know.</em>')}</h2></div><div class="faq">${faq(l,'cybercat')}</div></section>${relatedProducts(l)}${researchAgenda(l)}${cta(l)}`}
function faq(l,which){const list=which==='cybercat'?choose(l,[['¿Qué datos necesitamos?','Una pregunta técnica, la decisión que apoyará y una descripción de los datos que puedes compartir. No envíes archivos ni información confidencial en la primera consulta.'],['¿Qué recibo al finalizar?','Lo acordado en la propuesta: método, hallazgos, límites y próximos pasos. Si se incluye código o datos, se especificarán formatos y condiciones de entrega.'],['¿Se garantizan descubrimientos o una precisión?','No. Una investigación puede generar hipótesis, resultados negativos o límites del método. Los criterios de evaluación se acuerdan antes del trabajo.'],['¿Cómo se definen plazo y precio?','Tras revisar viabilidad, calidad de datos, cómputo y revisión humana. No hay una tarifa pública ni una operación continua garantizada.'],['¿Quién posee los resultados?','El contrato debe distinguir tecnología previa, recursos de terceros y resultados del proyecto. Los derechos se acuerdan expresamente.']],[['What data is needed?','A technical question, the decision it supports and a description of data you can share. Do not send files or confidential information in the initial enquiry.'],['What do I receive?','What is agreed in the proposal: method, findings, limitations and next steps. Any code or data deliverables will have specified formats and delivery conditions.'],['Are discoveries or accuracy guaranteed?','No. Research may generate hypotheses, negative results or method limitations. Evaluation criteria are agreed before work begins.'],['How are timing and pricing determined?','After reviewing feasibility, data quality, compute and human review. There is no public fixed rate or guaranteed continuous operation.'],['Who owns the results?','The contract must distinguish pre-existing technology, third-party resources and project results. Rights are expressly agreed.']]):[];return list.map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}
function infra(l){const t=ui[l];return `<section class="page-intro">${eyebrow(t.infrastructure)}<h1>${choose(l,'Entiende las restricciones.<br><em>Decide el siguiente paso.</em>','Understand the constraints.<br><em>Decide the next step.</em>')}</h1><p>${choose(l,'Investigación orientada a decisiones de infraestructura física de IA: energía, agua, sitios y vacíos de evidencia para inversionistas, desarrolladores y proveedores.','Decision-oriented research for physical AI infrastructure: power, water, sites and evidence gaps for investors, developers and suppliers.')}</p>${button(href(l,'contact')+'?type=infrastructure',t.evaluate)}</section><section class="section"><div class="service-grid">${choose(l,[['Energía e interconexión','Distinguir capacidad anunciada de disponibilidad verificable, condiciones de conexión y calendario.'],['Agua y refrigeración','Identificar necesidades, condiciones de suministro y vacíos que requieren una evaluación local.'],['Sitio y condiciones de avance','Organizar restricciones, dependencias y preguntas pendientes para definir una siguiente revisión.']],[['Power and interconnection','Distinguish announced capacity from verifiable availability, connection conditions and timing.'],['Water and cooling','Identify requirements, supply conditions and gaps requiring local assessment.'],['Site and decision gates','Organize constraints, dependencies and open questions to define the next review.']]).map(([a,b],i)=>`<article><span class="service-index">0${i+1}</span><h3>${a}</h3><p>${b}</p></article>`).join('')}</div></section><section class="section evidence-home"><div>${eyebrow(choose(l,'UN ENTREGABLE EVALUABLE','A REVIEWABLE DELIVERABLE'))}<h2>${choose(l,'Separa señales<br><em>de conclusiones.</em>','Separate signals<br><em>from conclusions.</em>')}</h2><p>${choose(l,'La propuesta de trabajo define la pregunta, fuentes, alcance geográfico y límites de evidencia. Los hallazgos se organizan para que el cliente pueda identificar qué se sabe y qué debe verificar.','The proposal defines the question, sources, geographic scope and evidence limitations. Findings help the client distinguish what is known from what needs verification.')}</p><p>${choose(l,'Esta investigación no sustituye estudios de ingeniería, asesoramiento jurídico o verificaciones locales.','This research does not replace engineering studies, legal advice or local verification.')}</p><a class="text-link" href="https://www.sagarlabs.com/${l}/" target="_blank" rel="noreferrer">${choose(l,'Consultar la plataforma pública actual','Visit the current public platform')} ↗</a></div>${samplePreview(l)}</section>${cta(l,'infrastructure')}`}
function titanUpdateLinks(l){return `<section class="section titan-update"><div>${eyebrow(choose(l,'ACTUALIZACIÓN / CYBERCAT + TITAN','UPDATE / CYBERCAT + TITAN'))}<h2>${choose(l,'Nuevas líneas.<br><em>Evidencia por construir.</em>','New directions.<br><em>Evidence to build.</em>')}</h2><p>${choose(l,'Propuestas de I+D con especificaciones, referencias comerciales y requisitos de validación explícitos.','R&D proposals with specifications, commercial references and explicit validation requirements.')}</p></div><div class="update-links">${['nas-mxene-battery','tetrataenite-magnet','graphene-thermal','titan-pikan-engine'].map(slug=>{const p=products.find(x=>x.slug===slug);return `<a href="${href(l,'product:'+slug)}"><span>${esc(p[l].title)}</span><small>${esc(p[l].price)}</small><b aria-hidden="true">↗</b></a>`}).join('')}</div></section>`}
function researchAgenda(l){const items=l==='es'?[
['Agua y separación','Explorar un objetivo inferior a 0.8 kWh/m³. Revisar límites termodinámicos, salinidad y recuperación antes de interpretar ese umbral.'],['Captura y mineralización de CO₂','Estudiar regeneración por debajo de 80 °C y rutas de mineralización. Requiere balances, cinética y estabilidad; no acredita captura certificada.'],['Energía para centros de datos','100 MW como escenario de diseño. Autonomía y agua son objetivos por evaluar con balances, suministro y requisitos de ingeniería.'],['Cooperación multiagente','Estudiar autoorganización y estabilidad. El umbral Φ > 0.75 es exploratorio y no constituye una medida demostrada de consciencia.']]:[
['Water and separation','Explore a target below 0.8 kWh/m³. Review thermodynamic limits, salinity and recovery before interpreting that threshold.'],['CO₂ capture and mineralization','Study regeneration below 80 °C and mineralization pathways. Requires balances, kinetics and stability; not certified capture.'],['Energy for data centers','100 MW as a design scenario. Autonomy and water use are goals to assess through balances, supply and engineering requirements.'],['Multiagent cooperation','Study self-organization and stability. The exploratory Φ > 0.75 threshold is not a demonstrated measure of consciousness.']];return `<section class="section agenda"><div class="section-heading"><div>${eyebrow(choose(l,'AGENDA PROPUESTA / [HYPOTHESIS]','PROPOSED AGENDA / [HYPOTHESIS]'))}<h2>${choose(l,'Cuatro preguntas<br><em>para investigar.</em>','Four questions<br><em>to investigate.</em>')}</h2></div><p>${choose(l,'Direcciones de trabajo, no resultados alcanzados. Cada piloto necesita método, fuentes y criterios de aceptación.','Research directions, not achieved results. Each pilot needs a method, sources and acceptance criteria.')}</p></div><div class="agenda-grid">${items.map(([title,body],i)=>`<article><span class="eyebrow">0${i+1} / [HYPOTHESIS]</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section>`}
function research(l){const t=ui[l];return `<section class="page-intro research-intro">${eyebrow(choose(l,'INVESTIGACIÓN Y LICENCIAS','RESEARCH & LICENSING'))}<h1>${choose(l,'Materia, software.<br><em>Nuevas posibilidades.</em>','Materials, software.<br><em>New possibilities.</em>')}</h1><p>${choose(l,'Nueve propuestas para energía, cómputo, materiales y agua: materiales, gemelos digitales y arquitectura de centros de datos. Explora sus visuales, datos reportados y condiciones para una posible licencia.','Nine proposals for energy, computing, materials and water: materials, digital twins and data center architecture. Explore their visuals, reported data and conditions for potential licensing.')}</p><p class="context-note">${choose(l,'No se ofrecen como tecnologías industrialmente validadas. El alcance, los derechos y la disponibilidad comercial requieren revisión.','These are not offered as industrially validated technologies. Scope, rights and commercial availability require review.')}</p></section>${titanUpdateLinks(l)}${showcase(l)}<section class="section collection" id="collection"><div class="filters" role="group" aria-label="${choose(l,'Filtrar investigación','Filter research')}">${['all','energy','compute','environment','software','architecture','industry'].map((f,i)=>`<button type="button" data-filter="${f}" aria-pressed="${i===0}" class="${i===0?'active':''}">${esc(t[f])}</button>`).join('')}</div><p id="filter-count" class="filter-count" aria-live="polite">${choose(l,products.length+' propuestas',products.length+' proposals')}</p><div class="products">${products.map((p,i)=>card(l,p,i)).join('')}</div><p class="context-note">${choose(l,'Las esculturas son representaciones artísticas conceptuales, no modelos atómicos ni evidencia experimental.','Sculptures are conceptual artistic representations, not atomic models or experimental evidence.')}</p></section>${cta(l,'licensing')}`}
function product(l,p){const t=ui[l],v=p[l],i=products.indexOf(p);return `<section class="section product-detail"><a class="text-link" href="${href(l,'research')}">← ${t.back}</a><div class="product-detail-grid"><div class="product" data-piece="${i}"><div class="product-art">${productArt(p,i)}</div><p class="context-note">${choose(l,'Render conceptual original. No representa un prototipo validado.','Original conceptual render. Not a validated prototype.')}</p>${p.render?`<a class="text-link render-download" href="${p.render}" download>${choose(l,'Descargar visual conceptual (SVG)','Download conceptual visual (SVG)')} ↗</a>`:''}</div><div>${eyebrow(v.category)}<h1>${esc(v.title)}</h1><span class="status">${esc(v.status||t.researchStatus)}</span><p>${esc(v.summary)}</p><p class="decision-question">${esc(v.question)}</p>${v.price?`<div class="price-panel"><strong>${esc(v.price)}</strong><p>${esc(v.priceNote)}</p></div>`:''}${button(href(l,'contact')+'?type=licensing&material='+p.slug,choose(l,'Consultar alcance y licencia','Discuss scope and licensing'))}<a class="text-link brief-download" href="/dossiers/${l}/${p.slug}.md" download>${choose(l,'Descargar ficha informativa','Download product brief')} ↓</a>${p.dossier?`<a class="text-link dossier-download" href="${p.dossier}" download>${choose(l,'Descargar dossier de demostración (JSON)','Download demonstration dossier (JSON)')} ↓</a>`:''}</div></div>${p.showcase?showcase(l):''}${v.metrics?`<section class="reported-data" aria-label="${choose(l,'Datos reportados por CyberCat','CyberCat reported data')}"><div class="report-heading">${eyebrow(choose(l,'ACTUALIZACIÓN CYBERCAT / 16 NOV 2026','CYBERCAT UPDATE / 16 NOV 2026'))}<p>${esc(v.dataNotice||choose(l,'Cifras comunicadas por Sagar Labs. Documentación primaria pendiente de revisión.','Figures supplied by Sagar Labs. Primary documentation pending review.'))}</p></div><div class="reported-metrics">${v.metrics.map(m=>`<div><strong>${esc(m.value)}</strong><span>${esc(m.label)}</span></div>`).join('')}</div></section>`:''}<div class="evidence-panels"><article><h2>${t.evidence}</h2><p>${esc(v.evidence)}</p><p class="context-note"><strong>${t.source}:</strong> ${esc(v.sourceNote||choose(l,'Informe de actualización proporcionado por Sagar Labs el 16 de noviembre de 2026. Los archivos de simulación, evaluación o implementación no están adjuntos a esta ficha.','Update report supplied by Sagar Labs on November 16, 2026. Simulation, evaluation or implementation files are not attached to this brief.'))}</p></article><article><h2>${t.requirements}</h2><ul>${v.requirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article><article><h2>${t.scope}</h2><p>${esc(v.scope)}</p><p>${choose(l,'Los derechos, entregables y criterios de aceptación se acuerdan por contrato. Esta ficha no acredita patente, exclusividad o certificación. No hay compra directa disponible.','Rights, deliverables and acceptance criteria are agreed by contract. This brief does not establish a patent, exclusivity or certification. Direct purchasing is not available.')}</p></article></div></section>`}
function sample(l){const t=ui[l];const rows=choose(l,[['01 / PREGUNTA','¿Qué evidencia justificaría comparar dos materiales de interfaz térmica en una siguiente fase de ensayos?'],['02 / ALCANCE','Revisión documental y diseño de una comparación. Este ejemplo no incluye ensayos, simulaciones ejecutadas ni resultados obtenidos.'],['03 / HECHO PROPORCIONADO','El proyecto hipotético propone comparar dos candidatos. No se atribuyen propiedades medidas a ninguno.'],['04 / HIPÓTESIS','Una diferencia de resistencia térmica de contacto podría cambiar la selección. Debe ensayarse con condiciones equivalentes.'],['05 / EVIDENCIA NECESARIA','Espesor, área, presión de contacto, carga térmica, método de medición, referencias e incertidumbre. Revisar también ciclos de operación.'],['06 / CRITERIO DE DECISIÓN','Acordar con el cliente una diferencia mínima relevante y un nivel de incertidumbre aceptable antes de realizar la comparación. No se fija aquí un umbral técnico universal.'],['07 / PRÓXIMO PASO','Definir un protocolo de ensayo y verificar que los dos candidatos pueden evaluarse con el mismo método. Si faltan datos, detener la conclusión y documentar el vacío.']],[['01 / QUESTION','What evidence would justify comparing two thermal interface materials in a next phase of testing?'],['02 / SCOPE','Documentary review and comparison design. This example includes no tests, executed simulations or obtained results.'],['03 / PROVIDED FACT','The hypothetical project proposes comparing two candidates. No measured properties are attributed to either.'],['04 / HYPOTHESIS','A difference in thermal contact resistance could change selection. It must be tested under equivalent conditions.'],['05 / EVIDENCE NEEDED','Thickness, area, contact pressure, thermal load, measurement method, baselines and uncertainty. Also review operating cycles.'],['06 / DECISION GATE','Agree with the client on a minimum meaningful difference and acceptable uncertainty before comparison. No universal technical threshold is prescribed here.'],['07 / NEXT STEP','Define a test protocol and verify both candidates can be assessed using the same method. If data is missing, withhold the conclusion and document the gap.']]);return `<section class="page-intro sample-intro">${eyebrow(t.sampleLabel)}<h1>${choose(l,'Así se ve<br><em>una pregunta bien planteada.</em>','What a well-framed<br><em>question looks like.</em>')}</h1><p>${choose(l,'Ejemplo de formato de un informe de decisión. Permite evaluar estructura y claridad; no demuestra resultados de CyberCat ni trabajo realizado para un cliente.','An example decision brief format. It demonstrates structure and clarity, not CyberCat results or work performed for a client.')}</p><div class="intro-actions"><button class="button dark" data-print>${t.print}${icon}</button>${button('/samples/decision-brief-'+l+'.md',t.download,'outline')}</div></section><section class="section sample-document"><div class="document-meta"><span>SL / SAMPLE 001</span><span>${choose(l,'15 NOV 2026 · VERSIÓN 1.0','15 NOV 2026 · VERSION 1.0')}</span></div><h2>${choose(l,'Comparación de interfaces térmicas','Thermal interface comparison')}</h2><span class="status">${t.sampleShort}</span>${rows.map(([a,b])=>`<article>${eyebrow(a)}<p>${b}</p></article>`).join('')}<p class="sample-disclaimer">${t.sampleLabel}</p></section>${cta(l)}`}
function about(l){return `<section class="page-intro">${eyebrow('SAGAR LABS')}<h1>${choose(l,'Una empresa.<br><em>Un método explícito.</em>','One company.<br><em>An explicit method.</em>')}</h1><p>${choose(l,'Sagar Labs es una empresa constituida en Estados Unidos. Su enfoque une inteligencia de infraestructura e investigación aplicada para organizar evidencia y apoyar decisiones.','Sagar Labs is a company incorporated in the United States. Its approach combines infrastructure intelligence and applied research to organize evidence and support decisions.')}</p></section><section class="section two-column"><div><h2>${choose(l,'Qué puedes<br><em>esperar del proceso.</em>','What to expect<br><em>from the process.</em>')}</h2><p>${choose(l,'CyberCat es un producto en evolución. Su incorporación a un proyecto se evalúa según la pregunta, los datos, las herramientas y la revisión necesaria.','CyberCat is an evolving product. Its use in a project is assessed against the question, data, tools and review required.')}</p></div><div class="principles-list">${choose(l,[['Evidencia trazable','Distinguir hechos, hipótesis, inferencias y preguntas abiertas.'],['Responsabilidad definida','La propuesta debe identificar quién ejecuta y quién revisa, antes de aceptar el proyecto.'],['Alcance claro','Acordar entregables, calendario, cómputo y condiciones de uso de datos.'],['Límites visibles','No equiparar una propuesta o simulación con una tecnología validada.']],[['Traceable evidence','Distinguish facts, hypotheses, inferences and open questions.'],['Defined accountability','The proposal must identify who performs and reviews the work before project acceptance.'],['Clear scope','Agree on deliverables, schedule, compute and data use conditions.'],['Visible limitations','Do not equate a proposal or simulation with a validated technology.']]).map(([a,b])=>`<article><h3>${a}</h3><p>${b}</p></article>`).join('')}</div></section>${cta(l)}`}
function contactPage(l){const t=ui[l];return `<section class="section contact-page"><div>${eyebrow('SAGAR LABS / '+t.contact)}<h1>${choose(l,'Empecemos por<br><em>tu pregunta.</em>','Let’s start with<br><em>your question.</em>')}</h1><p>${t.contactIntro}</p><p>${choose(l,'Comparte solo una descripción inicial. Los datos técnicos confidenciales se tratarían después de acordar las condiciones apropiadas.','Share an initial description only. Confidential technical data would be handled after appropriate terms are agreed.')}</p><a class="text-link" href="mailto:${contact}">${contact} ↗</a><p class="context-note">${choose(l,'Sin una fecha de respuesta garantizada. La recepción de una consulta no constituye aceptación del proyecto.','No response date is guaranteed. Receipt of an enquiry does not constitute project acceptance.')}</p></div><div class="enquiry-box"><form id="enquiry-form" action="/api/enquiries" method="post"><label>${t.name}<input name="name" autocomplete="name" required maxlength="100"></label><label>${t.email}<input type="email" name="email" autocomplete="email" required maxlength="160"></label><label>${t.company}<input name="company" autocomplete="organization" required maxlength="160"></label><label>${t.type}<select name="type">${[['pilot',t.pilot],['dedicated',t.dedicated],['infrastructure',t.infrastructure],['licensing',t.licensing],['other',t.other]].map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></label><label class="wide">${t.message}<textarea name="question" rows="5" required minlength="20" maxlength="3000"></textarea></label><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent wide"><input type="checkbox" name="consent" required><span>${t.privacy} <a href="${href(l,'privacy')}">${t.privacyLink} ↗</a></span></label><input type="hidden" name="lang" value="${l}"><p id="form-message" class="wide" role="status" aria-live="polite"></p><button class="button lime wide" type="submit">${t.submit}${icon}</button><noscript><p class="wide">${choose(l,'Para enviar sin JavaScript, escribe al correo que aparece en esta página.','To enquire without JavaScript, use the email address on this page.')}</p></noscript></form><div id="enquiry-success" hidden tabindex="-1"><span class="success-icon" aria-hidden="true">✓</span><h2>${t.success}</h2><p>${t.saved}</p><p class="reference">${t.reference}: <strong id="enquiry-reference"></strong></p><p id="local-receipt" class="context-note" hidden>${t.local}</p><a class="text-link" href="${href(l,'home')}">${t.home} ↗</a></div></div></section>`}
function privacy(l){return `<section class="section prose-page">${eyebrow(choose(l,'INFORMACIÓN SOBRE CONSULTAS','ENQUIRY INFORMATION'))}<h1>${choose(l,'Uso de tus datos<br><em>de contacto.</em>','How your contact<br><em>data is used.</em>')}</h1><p>${choose(l,'Este aviso describe el formulario de consulta de este avance de Sagar Labs. Antes de una publicación comercial deben confirmarse el proveedor de recepción y los datos completos de la entidad responsable.','This notice describes the enquiry form in this Sagar Labs preview. Before commercial publication, the receiving provider and the responsible entity’s full details must be confirmed.')}</p><h2>${choose(l,'Qué se recoge y para qué','What is collected and why')}</h2><p>${choose(l,'Nombre, correo profesional, empresa o equipo, tipo de proyecto y descripción de la pregunta. Se solicitan para revisar la viabilidad de una consulta y responder. No se utilizan aquí para suscripciones ni campañas.','Name, work email, company or team, project type and question description. These are requested to assess an enquiry and respond. They are not used here for subscriptions or campaigns.')}</p><h2>${choose(l,'Dónde se registra','Where it is recorded')}</h2><p>${choose(l,'En la vista previa local, las solicitudes se guardan en este equipo y se identifican expresamente como pruebas locales. En producción, el formulario solo confirma recepción si el almacenamiento configurado acepta el registro. Si no está disponible, muestra un error y ofrece contacto por correo.','In the local preview, enquiries are stored on this computer and explicitly identified as local tests. In production, the form only confirms receipt after configured storage accepts the record. If unavailable, it shows an error and offers email contact.')}</p><h2>${choose(l,'Conservación y acceso','Retention and access')}</h2><p>${choose(l,'En producción, los registros caducan a los 30 días. En la vista previa local, los registros vencidos se eliminan al recibir la siguiente consulta. La configuración final y los proveedores se deben confirmar antes del lanzamiento. Para solicitar revisión o eliminación de una consulta, escribe a','In production, records expire after 30 days. In the local preview, expired records are removed when the next enquiry is received. Final configuration and providers must be confirmed before launch. To request review or deletion of an enquiry, email')} <a href="mailto:${contact}">${contact}</a>.</p><h2>${choose(l,'Protección del formulario','Form protection')}</h2><p>${choose(l,'Se limita el número de envíos y se utiliza una referencia técnica derivada de la conexión para mitigar abuso. No se muestran datos personales en URLs de confirmación. No se cargan herramientas de publicidad o analítica de terceros en este avance.','Submission counts are limited and a technical identifier derived from the connection is used to mitigate abuse. Personal details do not appear in confirmation URLs. This preview loads no third-party advertising or analytics tools.')}</p></section>`}
const meta={es:{home:['Inteligencia de infraestructura e I+D asistida por IA','Sagar Labs conecta evidencia, infraestructura física e investigación aplicada. Explora CyberCat, servicios y propuestas de materiales.'],cybercat:['CyberCat: pilotos de I+D asistida por IA','Producto en evolución para evaluar proyectos de materiales, baterías y sistemas térmicos. Alcance, entregables y criterios acordados.'],infra:['Inteligencia para infraestructura física de IA','Investigación sobre energía, agua, sitios y restricciones para apoyar decisiones de infraestructura.'],research:['Investigación y propuestas de licencias tecnológicas','Explora nueve propuestas de investigación con estado documental, evidencia pendiente y alcance propuesto.'],sample:['Muestra ilustrativa de informe de decisión','Revisa un ejemplo de estructura de informe: pregunta, evidencia necesaria, hipótesis y criterios para decidir.'],about:['Cómo trabaja Sagar Labs','Empresa constituida en Estados Unidos. Enfoque de evidencia trazable, responsabilidad, alcance claro y límites explícitos.'],contact:['Evaluar un proyecto con Sagar Labs','Describe tu pregunta de infraestructura o investigación y solicita una revisión de viabilidad.'],privacy:['Información sobre datos de consultas','Cómo se utilizan los datos del formulario de consulta de Sagar Labs.']},en:{home:['Infrastructure intelligence and AI-assisted R&D','Sagar Labs connects evidence, physical infrastructure and applied research. Explore CyberCat, services and materials proposals.'],cybercat:['CyberCat: AI-assisted R&D pilots','An evolving product for evaluating materials, battery and thermal systems projects. Agreed scope, deliverables and evaluation criteria.'],infra:['Intelligence for physical AI infrastructure','Research into power, water, sites and constraints to support infrastructure decisions.'],research:['Research and technology licensing proposals','Explore nine research proposals with documentary status, evidence gaps and proposed scope.'],sample:['Illustrative decision brief sample','Review a sample brief structure: question, required evidence, hypotheses and decision criteria.'],about:['How Sagar Labs works','A company incorporated in the United States. Traceable evidence, accountability, clear scope and explicit limitations.'],contact:['Evaluate a project with Sagar Labs','Describe your infrastructure or research question and request a feasibility review.'],privacy:['Enquiry data information','How data from the Sagar Labs enquiry form is used.']}};
const keys=['home','cybercat','infra','research','sample','about','contact','privacy',...products.map(p=>'product:'+p.slug)];
function page(l,key){const t=ui[l],other=l==='es'?'en':'es',p=key.startsWith('product:')?products.find(x=>x.slug===key.slice(8)):null;const [title,desc]=p?[p[l].title+choose(l,' — Ficha técnica',' — Product brief'),p[l].summary]:meta[l][key];const canonical=siteURL+href(l,key);let content=p?product(l,p):({home,cybercat,infra,research,sample,about,contact:contactPage,privacy}[key])(l);if(key==='contact'&&process.env.ENQUIRIES_ENABLED==='false'){content=content.replace(/<form id="enquiry-form"[\s\S]*?<\/form>/,`<div class="contact-direct">${eyebrow(choose(l,'CONTACTO DIRECTO','DIRECT CONTACT'))}<h2>${choose(l,'Hablemos de<br><em>tu proyecto.</em>','Let’s discuss<br><em>your project.</em>')}</h2><p>${choose(l,'El formulario todavía no está habilitado para recibir consultas. Puedes escribirnos directamente con tu pregunta y una descripción inicial del proyecto.','The enquiry form is not yet enabled. Email us directly with your question and an initial project description.')}</p>${button('mailto:'+contact,choose(l,'Escribir a Sagar Labs','Email Sagar Labs'))}</div>`)}const organization={'@context':'https://schema.org','@type':'Organization','@id':siteURL+'/#organization',name:'Sagar Labs',url:siteURL,email:contact};const webpage={'@context':'https://schema.org','@type':key==='contact'?'ContactPage':key==='about'?'AboutPage':'WebPage',name:title,description:desc,url:canonical,inLanguage:l,isPartOf:{'@type':'WebSite',name:'Sagar Labs',url:siteURL},publisher:{'@id':organization['@id']}};const search=[...['home','cybercat','infra','research','sample','about','contact'].map(k=>({title:meta[l][k][0],url:href(l,k)})),...products.map(p=>({title:p[l].title+' · '+p[l].category,url:href(l,'product:'+p.slug)}))];return `<!doctype html><html lang="${l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101513"><title>${esc(title)} | Sagar Labs</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${canonical}"><link rel="alternate" hreflang="es" href="${siteURL+href('es',key)}"><link rel="alternate" hreflang="en" href="${siteURL+href('en',key)}"><link rel="alternate" hreflang="x-default" href="${siteURL+href('es',key)}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)} | Sagar Labs"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${canonical}"><meta property="og:locale" content="${l==='es'?'es_US':'en_US'}"><meta property="og:image" content="${siteURL}/assets/social-${l}.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${siteURL}/assets/social-${l}.png"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">${JSON.stringify(organization)}</script><script type="application/ld+json">${JSON.stringify(webpage)}</script></head><body data-page="${esc(key)}"><a class="skip-link" href="#main">${t.skip}</a><div class="reading-progress" aria-hidden="true"></div><header><a class="brand" href="${href(l,'home')}" aria-label="Sagar Labs · ${t.home}"><span class="mark">S</span>SAGAR<span class="light">LABS</span></a><nav id="main-nav" aria-label="${choose(l,'Navegación principal','Main navigation')}">${['cybercat','infra','research','about'].map((k,i)=>`<a href="${href(l,k)}"${key===k?' aria-current="page"':''}>${t.nav[i]}</a>`).join('')}</nav><div class="header-tools"><button id="quick-open" aria-label="${t.search}"><span aria-hidden="true">⌘ K</span></button><div class="languages" aria-label="${t.language}"><a href="${href('es',key)}" lang="es" hreflang="es"${l==='es'?' aria-current="true"':''}>ES</a><a href="${href('en',key)}" lang="en" hreflang="en"${l==='en'?' aria-current="true"':''}>EN</a></div></div><a class="nav-contact" href="${href(l,'contact')}">${t.contact} ↗</a><button id="menu" class="menu" aria-label="${t.menu}" aria-expanded="false" aria-controls="main-nav">☰</button></header><main id="main">${content}</main><footer><div><a class="brand" href="${href(l,'home')}">SAGAR<span class="light">LABS</span></a><p>${t.footer}</p></div><div class="footer-links"><a href="${href(l,'sample')}">${t.sample}</a><a href="${href(l,'about')}">${t.principles}</a><a href="${href(l,'privacy')}">${t.privacyLink}</a><a href="mailto:${contact}">${contact} ↗</a></div><p class="copyright">© 2026 Sagar Labs. ${t.rights}</p></footer><button id="motion" class="motion-global" aria-label="${t.motionPause}">Ⅱ</button><dialog id="command" aria-labelledby="command-title"><div class="command-top"><span id="command-title">${t.search}</span><button id="command-close" aria-label="${t.close}">ESC</button></div><input id="command-input" type="search" aria-label="${t.search}" placeholder="${t.searchPlaceholder}" autocomplete="off"><div id="command-results"></div><p class="command-help">${t.searchHelp}</p></dialog><script type="application/json" id="page-data">${JSON.stringify({lang:l,ui:t,search}).replaceAll('<','\\u003c')}</script><script src="/assets/main.js" defer></script>${key==='home'?'<script src="/assets/hero.js" defer></script>':''}${key==='cybercat'?'<script src="/assets/field.js" defer></script>':''}${key==='research'||p?'<script src="/assets/gallery.js" defer></script>':''}</body></html>`}
await fs.rm(out,{recursive:true,force:true});await fs.mkdir(out,{recursive:true});await fs.cp('assets',path.join(out,'assets'),{recursive:true});for(const l of ['es','en'])for(const key of keys){const target=path.join(out,href(l,key),'index.html');await fs.mkdir(path.dirname(target),{recursive:true});await fs.writeFile(target,page(l,key))}
